const $=s=>document.querySelector(s);
let route='all',period='day',category='全部',onlyUnseen=false,probabilityOrder='desc',collectionRarity='common',seen=new Set();
// Relative field estimate, not a guarantee or real-time population statistic.
const encounterBase={lion:25,leopard:10,cheetah:14,hyena:38,elephant:72,buffalo:70,rhino:8,hippo:32,giraffe:56,zebra:82,wildebeest:86,impala:88,thomson:76,grant:62,topi:45,eland:30,warthog:50,baboon:54,ostrich:42,crocodile:22,waterbuck:34,hartebeest:28,dikdik:18,jackal:30,serval:8,bateared:12,crane:18,secretary:11,bustard:20};
const nightLift={lion:1.15,leopard:1.65,cheetah:.7,hyena:1.45,elephant:1.05,buffalo:1.2,rhino:.75,hippo:1.35,giraffe:.55,zebra:.65,wildebeest:.7,impala:.8,thomson:.7,grant:.7,topi:.7,eland:.7,warthog:1.05,baboon:.55,ostrich:.45,crocodile:.8,waterbuck:.95,hartebeest:.65,dikdik:1.15,jackal:1.4,serval:1.75,bateared:1.8,crane:.5,secretary:.45,bustard:.5};
const birds=new Set(['ostrich','crane','secretary','bustard']);const reptiles=new Set(['crocodile']);
const kindOf=a=>birds.has(a.id)?'鸟类':reptiles.has(a.id)?'爬行动物':'哺乳动物';
function encounterScore(a){const raw=encounterBase[a.id]||20;const periodFactor=period==='night'?(nightLift[a.id]||1):1;return Math.max(1,Math.min(95,Math.round(raw*periodFactor)))}
function encounterLabel(a){return `约 ${encounterScore(a)}%`}
const RARITY_GROUPS=[{id:'common',name:'常见',min:55},{id:'uncommon',name:'少见',min:20},{id:'rare',name:'稀有',min:0}];
function rarityOf(a){const score=encounterBase[a.id]||20;return score>=55?'common':score>=20?'uncommon':'rare'}
try{const saved=JSON.parse(localStorage.getItem('safari-seen')||'[]');if(Array.isArray(saved))seen=new Set(saved.filter(id=>ANIMALS.some(a=>a.id===id)))}catch{}
const cats=['全部','有角的','大型动物','猫科','其他哺乳类','鸟类与爬行类'];const stripTags=s=>String(s||'').replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim();const escapeHtml=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#categories').innerHTML=cats.map(c=>`<button aria-pressed="${c===category}">${c}</button>`).join('');$('#categories').onclick=e=>{if(e.target.tagName!=='BUTTON')return;category=e.target.textContent;[...e.currentTarget.children].forEach(b=>b.setAttribute('aria-pressed',b.textContent===category));render()};$('#search').oninput=render;$('#seenFilter').onclick=()=>{onlyUnseen=!onlyUnseen;$('#seenFilter').setAttribute('aria-pressed',onlyUnseen);render()};$('#sortProbability').onclick=()=>{probabilityOrder=probabilityOrder==='desc'?'asc':'desc';const ascending=probabilityOrder==='asc';const button=$('#sortProbability');button.querySelector('span').textContent=ascending?'↑':'↓';button.setAttribute('aria-label',`按遇见概率从${ascending?'低到高':'高到低'}排序`);button.title=`遇见概率：从${ascending?'低到高':'高到低'}`;render()};
function persistFilters(){try{localStorage.setItem('safari-filters',JSON.stringify({route,period}))}catch{}}
async function preserveLocalRecords(){try{if(navigator.storage?.persist)await navigator.storage.persist()}catch{}}
function toggleSeen(id){seen.has(id)?seen.delete(id):seen.add(id);try{localStorage.setItem('safari-seen',JSON.stringify([...seen]));preserveLocalRecords()}catch{alert('本机未能保存记录，关闭后可能丢失。')}render()}
function render(){
 const q=$('#search').value.trim().toLowerCase();
 const list=ANIMALS.filter(a=>(route==='all'||a.locations.includes(route))&&a.periods.includes(period)&&(category==='全部'||a.groups.includes(category))&&(!onlyUnseen||!seen.has(a.id))&&JSON.stringify([a.name,a.en,a.latin,a.hint,a.traits,a.tags,a.label]).toLowerCase().includes(q)).sort((a,b)=>(probabilityOrder==='desc'?encounterScore(b)-encounterScore(a):encounterScore(a)-encounterScore(b))||a.name.localeCompare(b.name,'zh-CN'));
 const location=LOCATIONS.find(l=>l.id===route);
 $('#routeNote').textContent='';
 $('#count').textContent=`${list.length} 种动物${seen.size?` · 已见 ${seen.size} 种`:''}`;
 $('#empty').hidden=!!list.length;
 $('#empty').textContent=onlyUnseen?'当前筛选下的动物你都见过了。可取消“只看未见过”查看全部。':'没有符合当前条件的动物。试试其他地点、时段，或清空搜索。';renderCollection();
 $('#grid').innerHTML=list.map(a=>`<article class="card" data-animal="${a.id}"><button class="card-open" data-id="${a.id}" aria-label="查看${a.name}"><div class="photo"><img src="${a.image}" alt="${a.name}" loading="lazy" width="600" height="450"><span class="tag">${a.label}</span><span class="probability">${encounterLabel(a)}</span></div><div class="cardText"><h2>${a.name}</h2><p class="en">${a.en}</p><p class="hint">${a.hint}</p></div></button><button class="card-seen" data-seen="${a.id}" aria-pressed="${seen.has(a.id)}" aria-label="${seen.has(a.id)?'取消见过':'标记见过'}${a.name}">${seen.has(a.id)?'✓ 见过 · 取消':'＋ 见过'}</button></article>`).join('');
}
$('#grid').onclick=e=>{const mark=e.target.closest('[data-seen]');if(mark){const id=mark.dataset.seen;const old=[...$('#grid').querySelectorAll('[data-seen]')];const index=old.indexOf(mark);toggleSeen(id);const next=$('#grid').querySelector(`[data-seen="${id}"]`)||$('#grid').querySelectorAll('[data-seen]')[Math.min(index,$('#grid').querySelectorAll('[data-seen]').length-1)]||$('#seenFilter');next.focus({preventScroll:true});return}const card=e.target.closest('[data-id]');if(card)showAnimal(card.dataset.id)};
function storyHTML(a){
 const s=STORIES[a.id];if(!s)return '';
 const textLength=s.lead.length+s.sections.reduce((n,x)=>n+x.text.length,0);
 const sourceLink=(n)=>{const source=s.sources[n-1];return `<a class="reference" href="${escapeHtml(source.url)}" target="_blank" rel="noopener" aria-label="资料 ${n}：${escapeHtml(source.title)}">[${n}]</a>`};
 const photo=s.photo?`<figure class="story-photo"><img src="${escapeHtml(s.photo.image)}" alt="${escapeHtml(s.photo.caption)}" loading="lazy" width="1200" height="800"><figcaption>${escapeHtml(s.photo.caption)}<small>摄影：${escapeHtml(s.photo.author)} · <a href="${escapeHtml(s.photo.licenseUrl)}" target="_blank" rel="noopener">${escapeHtml(s.photo.license)}</a> · <a href="${escapeHtml(s.photo.source)}" target="_blank" rel="noopener">原图与授权 ↗</a> · 已缩小及压缩</small></figcaption></figure>`:'';
 return `<article class="wild-story" aria-label="${escapeHtml(a.name)}的野外故事"><p class="eyebrow">野外故事 · 约 ${Math.max(2,Math.ceil(textLength/350))} 分钟</p><h3 class="story-title">${escapeHtml(s.title)}</h3><p class="story-lead">${escapeHtml(s.lead)}</p>${s.sections.map((section,i)=>`<section><h4>${escapeHtml(section.title)}</h4><p>${escapeHtml(section.text)} <span class="story-refs">${section.refs.map(sourceLink).join(' ')}</span></p></section>${i===0?photo:''}`).join('')}<aside class="field-note"><p class="eyebrow">在现场，多看一眼</p><p>${escapeHtml(s.watch)}</p></aside><details class="story-sources"><summary>资料与延伸阅读 · ${s.sources.length} 篇</summary><p class="offline-reading"><b>离线版已包含：</b>上方正文已把这些资料中与识别、行为和现场观察有关的要点整理进本地图鉴；断网时可直接阅读。以下链接是原始出处，联网后可打开全文。</p><ol>${s.sources.map(source=>`<li><a href="${escapeHtml(source.url)}" target="_blank" rel="noopener">${escapeHtml(source.title)} ↗</a></li>`).join('')}</ol><p>资料整理：2026 年 9 月。优先采用保护机构、研究机构与论文；较早的物种档案用于基础生活史，不据此推断当前数量或保护等级。</p></details></article>`;
}
function moreCredit(a){const list=(typeof GALLERY!=='undefined'&&GALLERY[a.id])||[];if(!list.length)return '';const first=STORIES[a.id]?.photo?3:2;return '<br>更多照片：'+list.map((p,i)=>`第 ${first+i} 张 ${escapeHtml(p.author)} · ${p.licenseUrl?`<a href="${escapeHtml(p.licenseUrl)}" target="_blank" rel="noopener">${escapeHtml(p.license)}</a>`:escapeHtml(p.license)} · <a href="${escapeHtml(p.source)}" target="_blank" rel="noopener">来源 ↗</a>`).join('<br>')}
function galleryHTML(a){const imgs=[a.image];const extra=STORIES[a.id]?.photo?.image;if(extra&&extra!==a.image)imgs.push(extra);if(typeof GALLERY!=='undefined')(GALLERY[a.id]||[]).forEach(p=>imgs.push(p.file));return `<div class="detail-gallery-wrap"><div class="detail-gallery" aria-label="${a.name}图片，可左右滑动">${imgs.map((src,i)=>`<figure><img class="bg" src="${escapeHtml(src)}" alt="" aria-hidden="true"><img class="fg" src="${escapeHtml(src)}" alt="${escapeHtml(a.name)}${i?' · 场景图':''}"${i?' loading="lazy"':''}></figure>`).join('')}</div>${imgs.length>1?`<div class="gallery-swipe"><button class="gallery-prev" type="button" aria-label="上一张">‹</button><button class="gallery-next" type="button" aria-label="下一张">›</button></div><span class="gallery-count" aria-live="polite">1/${imgs.length}</span>`:''}</div>`}
function animalSoundHTML(a){
 const c=typeof CALLS!=='undefined'?CALLS[a.id]:null;if(!c)return '';
 const author=c.author?`录音：${escapeHtml(c.author)} · `:'';
 const play='<svg class="i-play" viewBox="0 0 24 24" aria-hidden="true"><path d="M8.2 4.9a1 1 0 0 1 1.5-.86l9.3 6.1a1 1 0 0 1 0 1.72l-9.3 6.1a1 1 0 0 1-1.5-.86z"/></svg>';
 const pause='<svg class="i-pause" viewBox="0 0 24 24" aria-hidden="true"><rect x="6" y="4.5" width="4.2" height="15" rx="1.4"/><rect x="13.8" y="4.5" width="4.2" height="15" rx="1.4"/></svg>';
 const info='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v5.2"/><path d="M12 7.6v.1" stroke-width="2.6"/></svg>';
 return `<section class="animal-sound" aria-label="叫声"><div class="sound-row"><button class="sound-play" type="button" aria-label="播放叫声" aria-pressed="false">${play}${pause}</button><div class="sound-title"><h3>${escapeHtml(c.label)}</h3>${c.related?'<span class="rel-tag">近缘种</span>':''}</div><button class="sound-info" type="button" aria-label="录音说明与来源" aria-expanded="false">${info}</button></div><audio preload="none"><source src="${escapeHtml(c.file)}" type="audio/mpeg"></audio><div class="sound-detail" hidden>${c.note?`<p>${escapeHtml(c.note)}</p>`:''}<a href="${escapeHtml(c.source)}" target="_blank" rel="noopener">${author}${escapeHtml(c.license)} · 录音来源与授权 ↗</a></div></section>`
}
function showAnimal(id){
 const a=ANIMALS.find(x=>x.id===id);if(!a)return;
 const similar=a.similar.map(id=>ANIMALS.find(x=>x.id===id)).filter(Boolean);
 $('#detailContent').innerHTML=`${galleryHTML(a)}<div class="pad"><h2 id="detailName">${a.name}</h2><p class="en">${a.en} <span class="latin"> / ${a.latin}</span></p><p class="detail-tags"><span class="cat-tag">${a.label}</span><span class="prob-tag">遇见概率 ${encounterLabel(a)}</span></p><section class="quick-identify"><h3>认准这几个特征</h3><ul class="traits">${a.traits.map(t=>`<li>${t}</li>`).join('')}</ul></section>${a.facts?`<section class="species-facts"><h3>数量与分布</h3><dl><div><dt>全球数量预估</dt><dd>${escapeHtml(a.facts.population)}</dd></div><div><dt>主要生活地区</dt><dd>${escapeHtml(a.facts.range)}</dd></div></dl><p class="facts-source">数据来源：<a href="${escapeHtml(a.facts.source)}" target="_blank" rel="noopener">${escapeHtml(a.facts.sourceLabel)} ↗</a></p></section>`:''}${animalSoundHTML(a)}${storyHTML(a)}${similar.length?`<h3>相似动物</h3><div class="compare">${similar.map(b=>`<button data-compare="${b.id}"><img src="${b.image}" alt="${b.name}"><span><b>${b.name}</b><br>${b.hint}</span></button>`).join('')}</div>`:''}<p class="credit">识别照片：${escapeHtml(stripTags(a.credit?.author))} · <a href="${escapeHtml(a.credit?.licenseUrl)}" target="_blank" rel="noopener">${escapeHtml(a.credit?.license)}</a><br><a href="${escapeHtml(a.credit?.source)}" target="_blank" rel="noopener">照片来源与授权 ↗</a>${moreCredit(a)}<br>照片以缩略图展示，部分已缩小尺寸及压缩。照片为物种示例；雌雄、年龄和个体外观可能不同。</p></div><div class="detail-bar"><button id="markSeen" class="primary" aria-pressed="${seen.has(id)}">${seen.has(id)?'✓ 见过 · 点击取消':'＋ 见过'}</button></div>`;
 {const snd=$('#detailContent .animal-sound');if(snd){const au=snd.querySelector('audio'),btn=snd.querySelector('.sound-play');const sync=()=>{const on=!au.paused&&!au.ended;snd.classList.toggle('playing',on);btn.setAttribute('aria-pressed',String(on));btn.setAttribute('aria-label',on?'暂停叫声':'播放叫声')};btn.onclick=()=>{au.paused||au.ended?au.play().catch(()=>{}):au.pause()};const inf=snd.querySelector('.sound-info'),det=snd.querySelector('.sound-detail');inf.onclick=()=>{const open=det.hidden;det.hidden=!open;inf.setAttribute('aria-expanded',String(open))};['play','pause','ended'].forEach(ev=>au.addEventListener(ev,sync))}}
 {const g=$('#detailContent .detail-gallery'),cnt=$('#detailContent .gallery-count');if(g&&cnt){g.onscroll=()=>{cnt.textContent=`${Math.min(g.children.length,Math.round(g.scrollLeft/g.clientWidth)+1)}/${g.children.length}`};const step=dir=>g.scrollTo({left:Math.max(0,Math.min(g.scrollWidth-g.clientWidth,g.scrollLeft+dir*g.clientWidth)),behavior:'smooth'});$('#detailContent .gallery-prev')?.addEventListener('click',()=>step(-1));$('#detailContent .gallery-next')?.addEventListener('click',()=>step(1))}}
 $('#markSeen').onclick=()=>{toggleSeen(id);$('#markSeen').textContent=seen.has(id)?'✓ 见过 · 点击取消':'＋ 见过';$('#markSeen').setAttribute('aria-pressed',seen.has(id))};
 $('#detailContent').querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>showAnimal(b.dataset.compare));
 if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;
}
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('close',()=>d.querySelectorAll('audio').forEach(x=>x.pause()));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
let registration;async function worker(){if(!('serviceWorker'in navigator))throw Error('请用 Safari 或 Chrome，通过安全网址打开。');registration=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;return registration.active||navigator.serviceWorker.controller}async function message(type,onProgress){const sw=await worker();return new Promise((resolve,reject)=>{const channel=new MessageChannel();let timer;function reset(){clearTimeout(timer);timer=setTimeout(()=>reject(Error('下载响应超时，请保持应用打开后重试。')),120000)}reset();channel.port1.onmessage=e=>{reset();if(e.data.progress!=null){onProgress?.(e.data);return}clearTimeout(timer);channel.port1.close();e.data.error?reject(Error(e.data.error)):resolve(e.data)};sw.postMessage({type},[channel.port2])})}
const OFFLINE_ICONS={download:'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.5V15"/><path d="m8 11 4 4 4-4"/><path d="M4.5 16.5V18a2.5 2.5 0 0 0 2.5 2.5h10a2.5 2.5 0 0 0 2.5-2.5v-1.5"/></svg>',ready:'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.75"/><path d="m8.25 12.25 2.5 2.5 5-5.5"/></svg>',chevron:'<svg class="icon chev" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg>'};
function setOfflineState(complete,loading=false){const button=$('#offlineOpen');if(!button)return;button.innerHTML=`${complete?OFFLINE_ICONS.ready:OFFLINE_ICONS.download}<span class="offline-title">离线资料</span><b>${complete?'已下载':loading?'下载中':'未下载'}</b>${OFFLINE_ICONS.chevron}`;button.classList.toggle('is-ready',!!complete);button.classList.toggle('is-loading',!complete&&!!loading);button.setAttribute('aria-label',complete?'离线资料已下载':loading?'离线资料下载中':'离线资料未下载，点按查看')}
const BUNDLED=location.protocol==='file:';
async function check(){if(BUNDLED){setOfflineState(true);const st=$('#downloadStatus');if(st)st.textContent=`本 App 已内置 ${ANIMALS.length} 种动物的照片、识别特征和故事，无需联网即可使用。`;const b=$('#download');if(b)b.hidden=true;return {complete:true,cached:0,total:0}}try{const s=await message('CHECK');setOfflineState(s.complete);$('#downloadStatus').textContent=s.complete?`本版已完整保存 ${ANIMALS.length} 种动物的照片、识别特征和完整故事。可开启飞行模式检查。`:`已保存 ${s.cached}/${s.total} 个文件，正在后台保存离线资料。`;$('#download').textContent=s.complete?'重新检查 / 补全离线资料':'立即补全离线资料';return s}catch(e){$('#downloadStatus').textContent=e.message;setOfflineState(false)}}
async function downloadOffline(){if(BUNDLED)return check();const b=$('#download');b.disabled=true;$('#progress').hidden=false;setOfflineState(false,true);try{if(navigator.storage?.persist)await navigator.storage.persist();await message('DOWNLOAD',p=>{$('#progress').value=p.progress;$('#downloadStatus').textContent=`正在保存 ${p.done}/${p.total} 个文件，请保持应用打开…`});await check()}catch(e){$('#downloadStatus').textContent='下载未完成：'+e.message+' 已保存的资料会保留，可以重试。';setOfflineState(false)}finally{b.disabled=false;$('#progress').hidden=true}}
async function autoDownload(){const state=await check();if(state&&!state.complete)await downloadOffline()}
function openOffline(){$('#offline').showModal();check()}$('#offlineOpen')?.addEventListener('click',openOffline);$('#helpOpen').onclick=openOffline;$('#download').onclick=downloadOffline;window.addEventListener('online',autoDownload);
$('#route').innerHTML=LOCATIONS.map(l=>`<option value="${l.id}">${l.label}</option>`).join('');
try{const saved=JSON.parse(localStorage.getItem('safari-filters')||'{}');if(LOCATIONS.some(l=>l.id===saved.route))route=saved.route;if(['day','night'].includes(saved.period))period=saved.period}catch{}
$('#route').value=route;
function updatePeriod(){document.querySelectorAll('[data-period]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.period===period))}
$('#route').onchange=e=>{route=e.target.value;persistFilters();render()};
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;updatePeriod();persistFilters();render()});
persistFilters();updatePeriod();render();autoDownload();

function renderCollection(){const grid=$('#collectionGrid');if(!grid)return;const total=ANIMALS.length,found=seen.size,percent=Math.round(found/total*100);const storage=$('#collectionStorage');if(storage)storage.textContent=`已保存在此设备 · ${found} 种记录`;$('#collectionCount').textContent=`${found} / ${total}`;$('#collectionPercent').textContent=`${percent}%`;$('#collectionFill').style.width=`${percent}%`;const progress=$('#rarityProgress');const groups=RARITY_GROUPS.map(group=>{const animals=ANIMALS.filter(a=>rarityOf(a)===group.id),seenCount=animals.filter(a=>seen.has(a.id)).length,ratio=animals.length?Math.round(seenCount/animals.length*100):0;return {...group,animals,seenCount,ratio}});if(progress){progress.innerHTML=groups.map(group=>`<button type="button" data-rarity="${group.id}" aria-pressed="${group.id===collectionRarity}"><span>${group.name}<small>${group.ratio}%</small></span><b>${group.seenCount}/${group.animals.length}</b><i aria-hidden="true"><em style="width:${group.ratio}%"></em></i></button>`).join('');progress.onclick=e=>{const button=e.target.closest('[data-rarity]');if(!button)return;collectionRarity=button.dataset.rarity;renderCollection()}}const active=groups.find(g=>g.id===collectionRarity)||groups[0];grid.setAttribute('aria-label',`${active.name}动物收集册`);grid.innerHTML=active.animals.slice().sort((a,b)=>Number(seen.has(b.id))-Number(seen.has(a.id))||a.name.localeCompare(b.name,'zh-CN')).map(a=>`<button class="collection-item ${seen.has(a.id)?'collected':''}" data-collection="${a.id}" aria-label="${a.name}${seen.has(a.id)?'，已见过':'，未见过'}"><span class="avatar"><img src="${a.image}" alt="" loading="lazy"></span><span>${a.name}</span></button>`).join('');grid.onclick=e=>{const item=e.target.closest('[data-collection]');if(item)showAnimal(item.dataset.collection)}}
const mobileGuide=$('#mobileGuide'),mobileMine=$('#mobileMine'),myPage=$('#myPage'),guidePage=$('#guidePage');
function showMobilePage(page){const mine=page==='mine';guidePage.hidden=mine;myPage.hidden=!mine;mobileGuide.setAttribute('aria-pressed',String(!mine));mobileMine.setAttribute('aria-pressed',String(mine));mobileGuide.classList.toggle('active',!mine);mobileMine.classList.toggle('active',mine);if(mine)renderCollection();window.scrollTo({top:0,behavior:'smooth'})}
mobileGuide?.addEventListener('click',()=>showMobilePage('home'));mobileMine?.addEventListener('click',()=>showMobilePage('mine'));
